242	    @Override
243	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
244	        HttpHeaders headers = new HttpHeaders();
245	        Visit visit = visitMapper.toVisit(visitFieldsDto);
246	        Pet pet = new Pet();
247	        pet.setId(petId);
248	        visit.setPet(pet);
249	        this.clinicService.saveVisit(visit);
250	        VisitDto visitDto = visitMapper.toVisitDto(visit);
251	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
252	            .buildAndExpand(visit.getId()).toUri());
253	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
